const isFraudPage = path.includes('fraud');

const App = isExecPage
 ? lazy(() => import('./exec-app'))
 : isDarkStorePage
 ? lazy(() => import('./dark-store-app'))
 : isFraudPage
 ? lazy(() => import('./fraud-app'))
 : lazy(() => import('./app'));

ReactDOM.createRoot(document.getElementById('root')!).render(
 <Suspense fallback={null}>
 <App />
 </Suspense>
);
